import { useState, useEffect } from 'react';
import client from '../../api/client';
import './Historial.css';

const formatCOP = (v) =>
  new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);

const estadoBadge = {
  abierta:  'badge badge-blue',
  guardada: 'badge badge-yellow',
  cerrada:  'badge badge-green',
  anulada:  'badge badge-red',
};

export default function Historial() {
  const [ventas, setVentas]       = useState([]);
  const [loading, setLoading]     = useState(true);
  const [filtroEstado, setFiltroEstado] = useState('');
  const [desde, setDesde]         = useState('');
  const [hasta, setHasta]         = useState('');
  const [detalle, setDetalle]     = useState(null);
  const [showAnular, setShowAnular] = useState(null);
  const [motivo, setMotivo]       = useState('');

  useEffect(() => { cargar(); }, [filtroEstado, desde, hasta]);

  const cargar = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filtroEstado) params.append('estado', filtroEstado);
      if (desde) params.append('desde', desde);
      if (hasta) params.append('hasta', hasta);
      const { data } = await client.get(`/api/ventas?${params}`);
      setVentas(data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const anular = async (id) => {
    try {
      await client.patch(`/api/ventas/${id}/anular`, { motivo });
      setShowAnular(null);
      setMotivo('');
      cargar();
    } catch (err) {
      alert(err.response?.data?.error || 'Error al anular');
    }
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">📋 Historial de Ventas</h1>
      </div>

      {/* Filtros */}
      <div className="card historial-filtros">
        <select value={filtroEstado} onChange={e => setFiltroEstado(e.target.value)}>
          <option value="">Todos los estados</option>
          <option value="abierta">Abierta</option>
          <option value="guardada">Guardada</option>
          <option value="cerrada">Cerrada</option>
          <option value="anulada">Anulada</option>
        </select>
        <input type="date" value={desde} onChange={e => setDesde(e.target.value)} />
        <input type="date" value={hasta} onChange={e => setHasta(e.target.value)} />
        <button className="btn btn-secondary" onClick={() => { setFiltroEstado(''); setDesde(''); setHasta(''); }}>
          Limpiar
        </button>
      </div>

      {/* Tabla */}
      <div className="card table-wrap" style={{ marginTop: 16 }}>
        {loading ? (
          <p style={{ padding: 20, color: '#888' }}>Cargando...</p>
        ) : ventas.length === 0 ? (
          <p style={{ padding: 20, color: '#888' }}>No hay ventas.</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Fecha</th>
                <th>Cliente</th>
                <th>Items</th>
                <th>Total</th>
                <th>Pago</th>
                <th>Estado</th>
                <th>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {ventas.map(v => (
                <tr key={v.id}>
                  <td><strong>#{v.id}</strong></td>
                  <td>{new Date(v.createdAt).toLocaleString('es-CO')}</td>
                  <td>{v.Cliente?.nombre || <span style={{ color: '#bbb' }}>—</span>}</td>
                  <td>{v.items?.length || 0} producto(s)</td>
                  <td><strong>{formatCOP(v.total)}</strong></td>
                  <td>{v.metodoPago || '—'}</td>
                  <td><span className={estadoBadge[v.estado] || 'badge badge-gray'}>{v.estado}</span></td>
                  <td>
                    <div className="historial-acciones">
                      <button className="btn btn-secondary" style={{ padding: '4px 10px', fontSize: '.78rem' }}
                        onClick={() => setDetalle(detalle?.id === v.id ? null : v)}>
                        {detalle?.id === v.id ? 'Ocultar' : 'Ver'}
                      </button>
                      {v.estado !== 'anulada' && (
                        <button className="btn btn-danger" style={{ padding: '4px 10px', fontSize: '.78rem' }}
                          onClick={() => setShowAnular(v)}>
                          Anular
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Detalle de venta */}
      {detalle && (
        <div className="card historial-detalle">
          <h3>Detalle — Venta #{detalle.id}</h3>
          <table>
            <thead>
              <tr>
                <th>Producto</th>
                <th>Precio unit.</th>
                <th>Cant.</th>
                <th>Subtotal</th>
              </tr>
            </thead>
            <tbody>
              {detalle.items?.map(item => (
                <tr key={item.id}>
                  <td>{item.Producto?.nombre || '?'}</td>
                  <td>{formatCOP(item.price)}</td>
                  <td>{item.quantity}</td>
                  <td>{formatCOP(item.subtotal)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="detalle-totales">
            <span>Subtotal: {formatCOP(detalle.subtotal)}</span>
            {detalle.descuentoValor > 0 && <span>Descuento: − {formatCOP(detalle.descuentoValor)}</span>}
            <strong>Total: {formatCOP(detalle.total)}</strong>
            {detalle.saldoDebe > 0 && <span className="badge badge-red">Debe: {formatCOP(detalle.saldoDebe)}</span>}
          </div>
        </div>
      )}

      {/* Modal anular */}
      {showAnular && (
        <div className="modal-overlay">
          <div className="modal-box">
            <h3>Anular venta #{showAnular.id}</h3>
            <p style={{ color: '#888', fontSize: '.88rem', margin: '8px 0 14px' }}>
              Esta acción restaura el stock. No se puede deshacer.
            </p>
            <textarea
              placeholder="Motivo de anulación (opcional)"
              value={motivo}
              onChange={e => setMotivo(e.target.value)}
              rows={3}
              style={{ marginBottom: 14 }}
            />
            <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
              <button className="btn btn-secondary" onClick={() => setShowAnular(null)}>Cancelar</button>
              <button className="btn btn-danger" onClick={() => anular(showAnular.id)}>Confirmar anulación</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
